// Hosts provide their project cwd. Keep stdin/stdout attached to the MCP server.
const { spawn } = require('node:child_process');
const path = require('node:path');

const [client, posixSource, windowsSource] = process.argv.slice(2);
if (!['codex', 'cursor', 'gemini', 'vscode'].includes(client)) {
  process.stderr.write('agentflow: expected a plugin client name\n');
  process.exit(1);
}
const embedded = process.argv[1] === '--embedded-launchers';
const launcher = path.resolve(__dirname, '../templates/repo/.agentflow/bin/agentflow');
const mcp = ['mcp', '--client', client];

let command = 'sh';
let args = embedded ? ['-c', posixSource, 'agentflow', ...mcp] : [launcher, ...mcp];
if (process.platform === 'win32') {
  command = 'powershell.exe';
  const script = embedded
    ? ['-Command', '& { ' + windowsSource + '\n} mcp --client ' + client]
    : ['-File', launcher + '.ps1', ...mcp];
  args = ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', ...script];
}

const server = spawn(command, args, { stdio: 'inherit' });
server.on('error', error => {
  process.stderr.write('agentflow: could not start the plugin launcher: ' + error.message + '\n');
  process.exitCode = 1;
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.kill(signal));
}
server.on('exit', (code, signal) => {
  process.exitCode = code ?? (signal === 'SIGINT' ? 130 : 1);
});

# agentflow project launcher for Windows (generated by `agentflow init`; commit it).
# Runs the installed agentflow, or bootstraps the latest stable release on first use.
$ErrorActionPreference = 'Stop'
$tag = $null
$commandArgs = $args
if ($args.Count -ge 1 -and $args[0] -eq '--bootstrap-release') {
  if ($args.Count -lt 2 -or $args[1] -cnotmatch '^v\d+\.\d+\.\d+$') { throw 'agentflow: invalid stable release tag' }
  $tag = $args[1]
  $commandArgs = @($args | Select-Object -Skip 2)
}

$cacheRoot = if ($env:LOCALAPPDATA) { Join-Path $env:LOCALAPPDATA 'agentflow' } else { Join-Path $HOME '.cache\agentflow' }
$pointer = Join-Path $cacheRoot 'current.txt'
if (Test-Path -LiteralPath $pointer -PathType Leaf) {
  $active = (Get-Content -LiteralPath $pointer -Raw).Trim()
  $exe = Join-Path $active 'agentflow.exe'
  if ((Test-Path -LiteralPath $exe -PathType Leaf) -and (!$tag -or $active -eq (Join-Path $cacheRoot $tag.Substring(1)))) { & $exe @commandArgs; exit $LASTEXITCODE }
}

if (-not (Get-Command gh -ErrorAction SilentlyContinue)) {
  [Console]::Error.WriteLine('agentflow: first run needs the GitHub CLI (gh) logged in to github.com')
  exit 1
}

$arch = if ([Environment]::Is64BitOperatingSystem) { 'amd64' } else { throw 'agentflow: unsupported architecture' }
if (!$tag) {
  $tag = gh release view --repo nscaledev/agentflow --json tagName -q .tagName
  if ($LASTEXITCODE -ne 0 -or @($tag).Count -ne 1 -or $tag -cnotmatch '^v\d+\.\d+\.\d+$') { throw 'agentflow: could not resolve the latest stable release' }
}
$ver = $tag.TrimStart('v')
$pkg = "agentflow_${ver}_windows_${arch}.zip"
$tmp = Join-Path ([IO.Path]::GetTempPath()) ([IO.Path]::GetRandomFileName())
New-Item -ItemType Directory -Path $tmp | Out-Null
try {
  [Console]::Error.WriteLine("agentflow: first run, installing $tag")
  gh release download $tag --repo nscaledev/agentflow --dir $tmp --pattern $pkg --pattern checksums.txt 2>&1 | ForEach-Object { [Console]::Error.WriteLine($_) }
  if ($LASTEXITCODE -ne 0) { throw "agentflow: download of $tag failed" }

  $want = (Select-String -LiteralPath (Join-Path $tmp 'checksums.txt') -Pattern " $([regex]::Escape($pkg))$").Line.Split(' ')[0]
  $got = (Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $tmp $pkg)).Hash.ToLower()
  if ($want -ne $got) { throw "agentflow: checksum mismatch for $pkg, not installing" }

  gh attestation verify (Join-Path $tmp $pkg) --repo nscaledev/agentflow --signer-workflow nscaledev/agentflow/.github/workflows/release.yml 2>&1 | ForEach-Object { [Console]::Error.WriteLine($_) }
  if ($LASTEXITCODE -ne 0) { throw 'agentflow: build attestation did not verify, not installing' }

  # Install atomically: extract into a private staging dir and move it into place, then
  # replace the pointer file with a rename, so concurrent first runs never see a partial
  # install or a half-written pointer.
  $dest = Join-Path $cacheRoot $ver
  New-Item -ItemType Directory -Force -Path $cacheRoot | Out-Null
  $stage = Join-Path $cacheRoot (".install." + [IO.Path]::GetRandomFileName())
  Expand-Archive -LiteralPath (Join-Path $tmp $pkg) -DestinationPath $stage -Force
  if (Test-Path -LiteralPath $dest) {
    Remove-Item -Recurse -Force -LiteralPath $stage
  } else {
    try { Move-Item -LiteralPath $stage -Destination $dest } catch { Remove-Item -Recurse -Force -LiteralPath $stage -ErrorAction SilentlyContinue }
  }
  if (-not (Test-Path -LiteralPath (Join-Path $dest 'agentflow.exe'))) { throw "agentflow: install of $ver failed" }
  $next = "$pointer." + [IO.Path]::GetRandomFileName()
  Set-Content -LiteralPath $next -Value $dest -NoNewline
  Move-Item -LiteralPath $next -Destination $pointer -Force
} finally {
  Remove-Item -Recurse -Force -LiteralPath $tmp -ErrorAction SilentlyContinue
}

& (Join-Path $dest 'agentflow.exe') @commandArgs
exit $LASTEXITCODE
